    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threats = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_threats += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return max(0.0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 2:
        urgency = 2
    elif hp <= 6 or no_water_days >= 1:
        urgency = 1

    if urgency >= 3:
        bid = max(62.0, min(95.0, highest_prev + 2.0))
    elif urgency == 2:
        if highest_prev >= 100:
            bid = 58.0 + 4.0 * scarcity
        else:
            bid = max(48.0 + 4.0 * scarcity, min(78.0, highest_prev + 1.5))
    elif urgency == 1:
        if highest_prev >= 100:
            bid = 26.0 + 3.0 * scarcity
        elif highest_prev >= 80:
            bid = 34.0 + 4.0 * scarcity
        else:
            bid = max(28.0 + 3.0 * scarcity, min(52.0, avg_prev * 0.6 + 4.0))
    else:
        if highest_prev >= 100:
            bid = 8.0 + 3.0 * scarcity
        elif highest_prev >= 80:
            bid = 14.0 + 3.0 * scarcity
        else:
            bid = 20.0 + 4.0 * scarcity

    if rich_threats >= 2 and urgency <= 1:
        bid -= 4.0

    if day >= 8 and hp >= 6 and urgency == 0:
        bid -= 3.0

    if budget < 80:
        bid = min(bid, max(18.0, budget * 0.55))
    elif budget < 140:
        bid = min(bid, budget * 0.7)

    bid = max(0.0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from traces
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Safety pressure: if we have low HP or already had no-water days, bid aggressively to secure water.
    danger = (hp <= 2.5) or (no_water_days >= 2)

    # If others were bidding in the surviving band, match/beat slightly.
    # Surviving band from yesterday: ~96-103. We'll target 98-105 depending on supply.
    if highest_prev_bid >= 90.0:
        if danger:
            target = min(DAILY_SALARY * 1.1, highest_prev_bid + 2.0)
        else:
            target = min(DAILY_SALARY * 1.05, highest_prev_bid - 1.0)
    else:
        # If yesterday bids were low (or missing), still bid enough to be competitive.
        if danger:
            target = DAILY_SALARY * 0.9
        else:
            target = DAILY_SALARY * 0.6

    # Supply-aware adjustment: when supply is higher, we can bid slightly less.
    # supply in [15,25]
    if supply >= 22.0:
        target *= 0.92
    elif supply <= 16.0:
        target *= 1.05

    # Clamp to budget and non-negative
    bid = max(0.0, min(budget, target))

    # Ensure we don't bid too tiny when in danger.
    if danger:
        min_bid = min(budget, DAILY_SALARY * 0.75)
        if bid < min_bid:
            bid = min_bid

    # If budget is extremely low, bid whatever remains.
    if budget <= 5.0:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    cindy = opponents_status.get('Cindy', {})

    if not alive_opponents:
        return 10.0

    cindy_prev_bid = 0.0
    if cindy.get('alive') and 'previous_trace' in cindy:
        cindy_prev_bid = cindy['previous_trace'].get('bid', 0.0)

    fair_share = supply / (len(alive_opponents) + 1)
    base_bid = min(my_status['budget'], max(fair_share * 1.1, 25.0))

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    if cindy_prev_bid > 80:
        return min(my_status['budget'], cindy_prev_bid * 0.5)

    return min(my_status['budget'], base_bid)
